nodes.exampleSchema:
Schema.Struct({
  claimId: ClaimId,
  articleId: ArticleId,
  value: Schema.NonEmptyString,
  language: SupportedLanguage,
  gender: Schema.NullOr(GrammaticalGender),
  provenance: ClaimProvenance,
  context: Schema.optionalKey(
    Schema.Union([
      Schema.TaggedStruct("PLACE_ARTICLE", {
        placeArticleId: PlaceArticleId,
      }),
      Schema.TaggedStruct("PROFILE_CONTEXT", {
        profileContextId: ProfileContextId,
      }),
      Schema.TaggedStruct("TEXT", {
        text: Schema.NonEmptyString,
      }),
    ]),
  ),
})

Schema.Record(
  ArticleId,
  Schema.Record(
    SupportedLanguage,
    Schema.optionalKey(
      Schema.NonEmptyArray(
        Schema.Struct({
          value: Schema.NonEmptyString,
          gender: Schema.NullOr(GrammaticalGender),
          sources: Schema.NonEmptyArray(
            Schema.Union([
              Schema.TaggedStruct("ContributorClaim", {
                claimId: ClaimId,
              }),
              Schema.TaggedStruct("GbifObservation", {
                observationId: ObservationId,
              }),
              Schema.TaggedStruct("WikidataObservation", {
                observationId: ObservationId,
              }),
            ]),
          ),
        }),
      ),
    ),
  ),
)

Schema.Record(
  ArticlePath,
  Schema.Union([
    Schema.TaggedStruct("CanonicalPath", {
      articleId: ArticleId,
    }),
    Schema.TaggedStruct("AlternativePath", {
      articleId: ArticleId,
      canonical: ArticlePath,
    }),
  ]),
)

Schema.Struct({
  claimId: ClaimId,
  articleId: ArticleId,
  taxonId: GbifTaxonId,
  provenance: ClaimProvenance.cases.CONTRIBUTOR,
})

Schema.Struct({
  observationId: ObservationId,
  wikidataSelection: Schema.Struct({
    wikidataId: WikidataId,
    articleId: ArticleId,
    provenance: WikidataSelectionProvenance,
  }),
  request: Schema.Struct({
    url: Schema.URLFromString,
    entityId: WikidataId,
  }),
  fetchedAt: Schema.DateTimeUtcFromString,
  response: Schema.Struct({
    entities: Schema.Record(
      WikidataId,
      Schema.StructWithRest(
        Schema.Struct({
          id: WikidataId,
          lastrevid: WikidataRevisionId,
          modified: Schema.DateTimeUtcFromString,
          labels: Schema.Record(
            Schema.NonEmptyString,
            Schema.Struct({
              language: Schema.NonEmptyString,
              value: Schema.NonEmptyString,
            }),
          ),
          descriptions: Schema.Record(
            Schema.NonEmptyString,
            Schema.Struct({
              language: Schema.NonEmptyString,
              value: Schema.NonEmptyString,
            }),
          ),
          aliases: Schema.Record(
            Schema.NonEmptyString,
            Schema.Array(
              Schema.Struct({
                language: Schema.NonEmptyString,
                value: Schema.NonEmptyString,
              }),
            ),
          ),
          claims: Schema.Record(
            WikidataPropertyId,
            Schema.Array(
              Schema.StructWithRest(
                Schema.Struct({
                  id: WikidataStatementId,
                  mainsnak: Schema.JsonObject,
                  rank: Schema.NonEmptyString,
                  references: Schema.optionalKey(Schema.Array(Schema.JsonObject)),
                }),
                [Schema.JsonObject],
              ),
            ),
          ),
          sitelinks: Schema.Record(Schema.NonEmptyString, Schema.JsonObject),
        }),
        [Schema.JsonObject],
      ),
    ),
  }),
})

Schema.Record(
  GbifTaxonId,
  Schema.Struct({
    articleId: ArticleId,
    provenance: GbifSelectionProvenance,
    checklistKey: GbifChecklistKey,
  }),
)

Schema.Struct({
  kind: Schema.Literal("TAXON_METADATA"),
  observationId: ObservationId,
  taxonSelection: Schema.Struct({
    taxonId: GbifTaxonId,
    articleId: ArticleId,
    provenance: GbifSelectionProvenance,
    checklistKey: GbifChecklistKey,
  }),
  fetchedAt: Schema.DateTimeUtcFromString,
  response: Schema.Struct({
    taxonID: GbifTaxonId,
    scientificName: Schema.NonEmptyString,
    taxonRank: Schema.NonEmptyString,
    classification: Schema.Array(
      Schema.Struct({
        taxonID: GbifTaxonId,
        scientificName: Schema.NonEmptyString,
        taxonRank: Schema.NonEmptyString,
      }),
    ),
    vernacularNames: Schema.Array(
      Schema.Struct({
        vernacularName: Schema.NonEmptyString,
        language: Schema.NonEmptyString,
      }),
    ),
    distributions: Schema.Array(
      Schema.Struct({
        locality: Schema.NonEmptyString,
        establishmentMeans: Schema.NonEmptyString,
        remarks: Schema.optionalKey(Schema.String),
      }),
    ),
  }),
})

Schema.Record(
  ArticleId,
  Schema.Struct({
    observationId: ObservationId,
    classification: Schema.Array(
      Schema.Struct({
        taxonId: GbifTaxonId,
        scientificName: Schema.NonEmptyString,
        taxonRank: Schema.NonEmptyString,
      }),
    ),
  }),
)

Schema.Record(
  ArticleId,
  Schema.Struct({
    observationId: ObservationId,
    records: Schema.Array(
      Schema.Struct({
        occurrenceKey: GbifOccurrenceKey,
        datasetKey: GbifDatasetKey,
        eventDate: Schema.optionalKey(Schema.NonEmptyString),
        basisOfRecord: Schema.NonEmptyString,
        matchedTaxonId: GbifTaxonId,
        placeArticleId: Schema.optionalKey(PlaceArticleId),
        matchMethod: Schema.optionalKey(Schema.NonEmptyString),
      }),
    ),
  }),
)

Schema.Struct({
  claimId: ClaimId,
  articleId: ArticleId,
  minimumCm: Schema.optionalKey(Schema.Finite),
  maximumCm: Schema.optionalKey(Schema.Finite),
  provenance: ClaimProvenance,
  context: Schema.optionalKey(
    Schema.Union([
      Schema.TaggedStruct("PLACE_ARTICLE", {
        placeArticleId: PlaceArticleId,
        period: Schema.optionalKey(
          Schema.Struct({
            start: Schema.NonEmptyString,
            end: Schema.NullOr(Schema.NonEmptyString),
          }),
        ),
        practices: Schema.optionalKey(
          Schema.Struct({
            plantingMethod: Schema.optionalKey(Schema.NonEmptyString),
            groundCover: Schema.optionalKey(Schema.NonEmptyString),
            pesticides: Schema.optionalKey(Schema.NonEmptyString),
          }),
        ),
      }),
      Schema.TaggedStruct("PROFILE_CONTEXT", {
        profileContextId: ProfileContextId,
        period: Schema.optionalKey(
          Schema.Struct({
            start: Schema.NonEmptyString,
            end: Schema.NullOr(Schema.NonEmptyString),
          }),
        ),
        practices: Schema.optionalKey(
          Schema.Struct({
            plantingMethod: Schema.optionalKey(Schema.NonEmptyString),
            groundCover: Schema.optionalKey(Schema.NonEmptyString),
            pesticides: Schema.optionalKey(Schema.NonEmptyString),
          }),
        ),
      }),
      Schema.TaggedStruct("TEXT", {
        text: Schema.NonEmptyString,
        period: Schema.optionalKey(
          Schema.Struct({
            start: Schema.NonEmptyString,
            end: Schema.NullOr(Schema.NonEmptyString),
          }),
        ),
        practices: Schema.optionalKey(
          Schema.Struct({
            plantingMethod: Schema.optionalKey(Schema.NonEmptyString),
            groundCover: Schema.optionalKey(Schema.NonEmptyString),
            pesticides: Schema.optionalKey(Schema.NonEmptyString),
          }),
        ),
      }),
    ]),
  ),
})

Schema.Record(
  ArticleId,
  Schema.Struct({
    minimumCm: Schema.optionalKey(Schema.Finite),
    maximumCm: Schema.optionalKey(Schema.Finite),
    sources: Schema.NonEmptyArray(
      Schema.Union([
        Schema.TaggedStruct("ContributorClaim", {
          claimId: ClaimId,
        }),
        Schema.TaggedStruct("ExternalObservation", {
          observationId: ObservationId,
        }),
      ]),
    ),
    parentRange: Schema.optionalKey(
      Schema.Struct({
        minimumCm: Schema.optionalKey(Schema.Finite),
        maximumCm: Schema.optionalKey(Schema.Finite),
      }),
    ),
  }),
)

Schema.Struct({
  articleId: ArticleId,
  canonicalPath: ArticlePath,
  names: Schema.Record(
    SupportedLanguage,
    Schema.optionalKey(
      Schema.NonEmptyArray(
        Schema.Struct({
          value: Schema.NonEmptyString,
          gender: Schema.NullOr(GrammaticalGender),
          sources: Schema.NonEmptyArray(
            Schema.Union([
              Schema.TaggedStruct("ContributorClaim", {
                claimId: ClaimId,
              }),
              Schema.TaggedStruct("GbifObservation", {
                observationId: ObservationId,
              }),
              Schema.TaggedStruct("WikidataObservation", {
                observationId: ObservationId,
              }),
            ]),
          ),
        }),
      ),
    ),
  ),
  geographicalOrigin: Schema.optionalKey(
    Schema.Struct({
      gbif: Schema.optionalKey(
        Schema.Struct({
          observationId: ObservationId,
        }),
      ),
      contributorByLanguage: Schema.Record(
        SupportedLanguage,
        Schema.optionalKey(
          Schema.Struct({
            claimId: ClaimId,
            text: Schema.NonEmptyString,
          }),
        ),
      ),
    }),
  ),
  occurrenceSample: Schema.optionalKey(
    Schema.Struct({
      observationId: ObservationId,
      records: Schema.Int,
    }),
  ),
  taxonomy: Schema.optionalKey(
    Schema.Struct({
      observationId: ObservationId,
      classification: Schema.Array(
        Schema.Struct({
          taxonId: GbifTaxonId,
          scientificName: Schema.NonEmptyString,
          taxonRank: Schema.NonEmptyString,
        }),
      ),
    }),
  ),
  height: Schema.optionalKey(
    Schema.Struct({
      minimumCm: Schema.optionalKey(Schema.Finite),
      maximumCm: Schema.optionalKey(Schema.Finite),
      sources: Schema.NonEmptyArray(
        Schema.Union([
          Schema.TaggedStruct("ContributorClaim", {
            claimId: ClaimId,
          }),
          Schema.TaggedStruct("ExternalObservation", {
            observationId: ObservationId,
          }),
        ]),
      ),
      parentRange: Schema.optionalKey(
        Schema.Struct({
          minimumCm: Schema.optionalKey(Schema.Finite),
          maximumCm: Schema.optionalKey(Schema.Finite),
        }),
      ),
    }),
  ),
  images: Schema.optionalKey(
    Schema.Struct({
      observationId: ObservationId,
      assets: Schema.Array(
        Schema.Struct({
          mediaAssetId: MediaAssetId,
        }),
      ),
    }),
  ),
})

Schema.Record(
  ArticleId,
  Schema.Struct({
    gbif: Schema.optionalKey(
      Schema.Struct({
        observationId: ObservationId,
      }),
    ),
    contributorByLanguage: Schema.Record(
      SupportedLanguage,
      Schema.optionalKey(
        Schema.Struct({
          claimId: ClaimId,
          text: Schema.NonEmptyString,
        }),
      ),
    ),
  }),
)

Schema.Struct({
  kind: Schema.Literal("TAXON_OCCURRENCES"),
  observationId: ObservationId,
  taxonSelection: Schema.Struct({
    taxonId: GbifTaxonId,
    articleId: ArticleId,
    provenance: GbifSelectionProvenance,
    checklistKey: GbifChecklistKey,
  }),
  fetchedAt: Schema.DateTimeUtcFromString,
  query: Schema.Struct({
    occurrenceStatus: Schema.Literal("DETECTED"),
    hasGeospatialIssue: Schema.Literal(false),
    country: Schema.optionalKey(Schema.NonEmptyString),
    limit: Schema.Int,
  }),
  response: Schema.Struct({
    offset: Schema.Int,
    limit: Schema.Int,
    count: Schema.Int,
    endOfRecords: Schema.Boolean,
    results: Schema.Array(
      Schema.Struct({
        key: GbifOccurrenceKey,
        datasetKey: GbifDatasetKey,
        eventDate: Schema.optionalKey(Schema.String),
        basisOfRecord: Schema.NonEmptyString,
        countryCode: Schema.optionalKey(Schema.NonEmptyString),
        stateProvince: Schema.optionalKey(Schema.NonEmptyString),
        classifications: Schema.Record(
          GbifChecklistKey,
          Schema.Struct({
            acceptedUsage: Schema.Struct({
              key: GbifTaxonId,
            }),
          }),
        ),
        media: Schema.Array(
          Schema.Struct({
            type: Schema.NonEmptyString,
            identifier: Schema.URLFromString,
            creator: Schema.optionalKey(Schema.NonEmptyString),
            license: Schema.optionalKey(Schema.NonEmptyString),
          }),
        ),
      }),
    ),
  }),
})

Schema.Record(
  ArticleId,
  Schema.Struct({
    observationId: ObservationId,
    assets: Schema.Array(
      Schema.Struct({
        mediaAssetId: MediaAssetId,
      }),
    ),
  }),
)

Schema.Record(
  ObservationId,
  Schema.Union([
    Schema.Struct({
      kind: Schema.Literal("TAXON_METADATA"),
      taxonSelection: Schema.Struct({
        taxonId: GbifTaxonId,
        articleId: ArticleId,
        provenance: GbifSelectionProvenance,
        checklistKey: GbifChecklistKey,
      }),
      fetchedAt: Schema.DateTimeUtcFromString,
      response: Schema.Struct({
        taxonID: GbifTaxonId,
        scientificName: Schema.NonEmptyString,
        taxonRank: Schema.NonEmptyString,
        classification: Schema.Array(
          Schema.Struct({
            taxonID: GbifTaxonId,
            scientificName: Schema.NonEmptyString,
            taxonRank: Schema.NonEmptyString,
          }),
        ),
        vernacularNames: Schema.Array(
          Schema.Struct({
            vernacularName: Schema.NonEmptyString,
            language: Schema.NonEmptyString,
          }),
        ),
        distributions: Schema.Array(
          Schema.Struct({
            locality: Schema.NonEmptyString,
            establishmentMeans: Schema.NonEmptyString,
            remarks: Schema.optionalKey(Schema.String),
          }),
        ),
      }),
    }),
    Schema.Struct({
      kind: Schema.Literal("TAXON_OCCURRENCES"),
      taxonSelection: Schema.Struct({
        taxonId: GbifTaxonId,
        articleId: ArticleId,
        provenance: GbifSelectionProvenance,
        checklistKey: GbifChecklistKey,
      }),
      fetchedAt: Schema.DateTimeUtcFromString,
      query: Schema.Struct({
        occurrenceStatus: Schema.Literal("DETECTED"),
        hasGeospatialIssue: Schema.Literal(false),
        country: Schema.optionalKey(Schema.NonEmptyString),
        limit: Schema.Int,
      }),
      response: Schema.Struct({
        offset: Schema.Int,
        limit: Schema.Int,
        count: Schema.Int,
        endOfRecords: Schema.Boolean,
        results: Schema.Array(
          Schema.Struct({
            key: GbifOccurrenceKey,
            datasetKey: GbifDatasetKey,
            eventDate: Schema.optionalKey(Schema.String),
            basisOfRecord: Schema.NonEmptyString,
            countryCode: Schema.optionalKey(Schema.NonEmptyString),
            stateProvince: Schema.optionalKey(Schema.NonEmptyString),
            classifications: Schema.Record(
              GbifChecklistKey,
              Schema.Struct({
                acceptedUsage: Schema.Struct({
                  key: GbifTaxonId,
                }),
              }),
            ),
            media: Schema.Array(
              Schema.Struct({
                type: Schema.NonEmptyString,
                identifier: Schema.URLFromString,
                creator: Schema.optionalKey(Schema.NonEmptyString),
                license: Schema.optionalKey(Schema.NonEmptyString),
              }),
            ),
          }),
        ),
      }),
    }),
  ]),
)

Schema.Struct({
  taxonSelection: Schema.Struct({
    taxonId: GbifTaxonId,
    articleId: ArticleId,
    provenance: GbifSelectionProvenance,
    checklistKey: GbifChecklistKey,
  }),
  reason: Schema.NonEmptyString,
  requests: Schema.Array(
    Schema.Union([
      Schema.Struct({
        kind: Schema.Literal("TAXON_METADATA"),
        taxonId: GbifTaxonId,
        checklistKey: GbifChecklistKey,
        idempotencyKey: Schema.NonEmptyString,
      }),
      Schema.Struct({
        kind: Schema.Literal("TAXON_OCCURRENCES"),
        taxonId: GbifTaxonId,
        checklistKey: GbifChecklistKey,
        query: Schema.Struct({
          occurrenceStatus: Schema.Literal("DETECTED"),
          hasGeospatialIssue: Schema.Literal(false),
          country: Schema.optionalKey(Schema.NonEmptyString),
          limit: Schema.Int,
        }),
        idempotencyKey: Schema.NonEmptyString,
      }),
    ]),
  ),
})

Schema.Struct({
  claimId: ClaimId,
  articleId: ArticleId,
  wikidataId: WikidataId,
  provenance: ClaimProvenance.cases.CONTRIBUTOR,
})

Schema.Record(
  WikidataId,
  Schema.Struct({
    articleId: ArticleId,
    provenance: WikidataSelectionProvenance,
  }),
)

Schema.Struct({
  wikidataSelection: Schema.Struct({
    wikidataId: WikidataId,
    articleId: ArticleId,
    provenance: WikidataSelectionProvenance,
  }),
  reason: Schema.NonEmptyString,
  idempotencyKey: Schema.NonEmptyString,
  request: Schema.Struct({
    url: Schema.URLFromString,
    entityId: WikidataId,
  }),
})

Schema.Record(
  WikidataId,
  Schema.Struct({
    selected: Schema.Struct({
      articleId: ArticleId,
      claimId: ClaimId,
    }),
    conflicting: Schema.NonEmptyArray(
      Schema.Struct({
        articleId: ArticleId,
        claimId: ClaimId,
      }),
    ),
    since: Schema.DateTimeUtcFromString,
  }),
)

Schema.Record(
  GbifTaxonId,
  Schema.Struct({
    selected: Schema.Struct({
      articleId: ArticleId,
      provenance: GbifSelectionProvenance,
    }),
    conflicting: Schema.NonEmptyArray(
      Schema.Struct({
        articleId: ArticleId,
        provenance: GbifSelectionProvenance,
      }),
    ),
    since: Schema.DateTimeUtcFromString,
  }),
)

Schema.Array(
  Schema.Union([
    Schema.Struct({
      kind: Schema.Literal("WIKIDATA_ID_CONFLICT"),
      wikidataId: WikidataId,
      since: Schema.DateTimeUtcFromString,
    }),
    Schema.Struct({
      kind: Schema.Literal("GBIF_TAXON_ID_CONFLICT"),
      taxonId: GbifTaxonId,
      since: Schema.DateTimeUtcFromString,
    }),
    Schema.Struct({
      kind: Schema.Literal("CLAIM_REPORTS"),
      target: Schema.Union([
        Schema.Struct({
          kind: Schema.Literal("CLAIM"),
          claimId: ClaimId,
        }),
        Schema.Struct({
          kind: Schema.Literal("OBSERVATION_VALUE"),
          valueKey: ObservationValueKey,
        }),
      ]),
      reasons: Schema.NonEmptyArray(
        Schema.Literals([
          "ABUSIVE",
          "SPAM",
          "FALSE",
          "DANGEROUS",
          "MISTAKEN",
          "OFF_TOPIC",
          "WRONG_ENTITY",
        ]),
      ),
      since: Schema.DateTimeUtcFromString,
    }),
    Schema.Struct({
      kind: Schema.Literal("EXTERNAL_FETCH_FAILED"),
      target: Schema.Union([
        Schema.Struct({
          kind: Schema.Literal("WIKIDATA"),
          wikidataId: WikidataId,
        }),
        Schema.Struct({
          kind: Schema.Literal("GBIF"),
          taxonId: GbifTaxonId,
          checklistKey: GbifChecklistKey,
        }),
      ]),
      error: Schema.Literals(["NOT_FOUND", "REDIRECTED"]),
      since: Schema.DateTimeUtcFromString,
    }),
  ]),
)

Schema.Union([
  Schema.TaggedStruct("ADDED", {
    profileContextId: ProfileContextId,
    personId: PersonId,
    label: Schema.optionalKey(Schema.NonEmptyString),
    period: Schema.Struct({
      start: Schema.NonEmptyString,
      end: Schema.NullOr(Schema.NonEmptyString),
    }),
    visibility: InformationVisibility,
    dimensions: Schema.Array(
      Schema.Union([
        Schema.TaggedStruct("LOCATION", {
          place: Schema.TaggedStruct("GAZETTEER_PLACE", {
            placeArticleId: PlaceArticleId,
          }),
          elevation: Schema.optionalKey(
            Schema.Union([
              Schema.TaggedStruct("MEASURED", {
                source: Schema.NonEmptyString,
                meters: Schema.Finite,
              }),
              Schema.TaggedStruct("DECLARED", {
                meters: Schema.Finite,
              }),
            ]),
          ),
        }),
        Schema.TaggedStruct("PRODUCTION", {
          value: Schema.TaggedStruct("DECLARED", {
            kind: Schema.NonEmptyString,
          }),
        }),
      ]),
    ),
  }),
  Schema.TaggedStruct("DELETED", {
    profileContextId: ProfileContextId,
    personId: PersonId,
  }),
])

Schema.Record(
  ProfileContextId,
  Schema.Struct({
    personId: PersonId,
    label: Schema.optionalKey(Schema.NonEmptyString),
    period: Schema.Struct({
      start: Schema.NonEmptyString,
      end: Schema.NullOr(Schema.NonEmptyString),
    }),
    visibility: InformationVisibility,
    dimensions: Schema.Array(
      Schema.Union([
        Schema.TaggedStruct("LOCATION", {
          place: Schema.TaggedStruct("GAZETTEER_PLACE", {
            placeArticleId: PlaceArticleId,
          }),
          elevation: Schema.optionalKey(
            Schema.Union([
              Schema.TaggedStruct("MEASURED", {
                source: Schema.NonEmptyString,
                meters: Schema.Finite,
              }),
              Schema.TaggedStruct("DECLARED", {
                meters: Schema.Finite,
              }),
            ]),
          ),
        }),
        Schema.TaggedStruct("PRODUCTION", {
          value: Schema.TaggedStruct("DECLARED", {
            kind: Schema.NonEmptyString,
          }),
        }),
      ]),
    ),
  }),
)

Schema.Struct({
  placeArticleId: PlaceArticleId,
  whosOnFirstId: WhosOnFirstId,
  boundarySource: Schema.NonEmptyString,
  dataset: Schema.NonEmptyString,
  computedAt: Schema.DateTimeUtcFromString,
  months: Schema.Record(
    Schema.String.check(Schema.isPattern(/^(?:[1-9]|1[0-2])$/)),
    Schema.Struct({
      temperatureMeanC: Schema.Struct({
        mean: Schema.Finite,
        p10: Schema.Finite,
        p50: Schema.Finite,
        p90: Schema.Finite,
      }),
      precipitationMm: Schema.Struct({
        mean: Schema.Finite,
        p10: Schema.Finite,
        p50: Schema.Finite,
        p90: Schema.Finite,
      }),
    }),
  ),
  elevationBands: Schema.Array(
    Schema.Struct({
      minimumMeters: Schema.Finite,
      maximumMeters: Schema.Finite,
      fractionOfPlace: Schema.Finite,
      months: Schema.Record(
        Schema.String.check(Schema.isPattern(/^(?:[1-9]|1[0-2])$/)),
        Schema.Struct({
          temperatureMeanC: Schema.Struct({
            mean: Schema.Finite,
            p10: Schema.Finite,
            p50: Schema.Finite,
            p90: Schema.Finite,
          }),
          precipitationMm: Schema.Struct({
            mean: Schema.Finite,
            p10: Schema.Finite,
            p50: Schema.Finite,
            p90: Schema.Finite,
          }),
        }),
      ),
    }),
  ),
})

Schema.Record(
  PlaceArticleId,
  Schema.Struct({
    dataset: Schema.NonEmptyString,
    annualMeanTemperatureC: Schema.Finite,
    annualPrecipitationMm: Schema.Finite,
    rainfallPattern: Schema.NonEmptyString,
    elevationBands: Schema.Array(
      Schema.Struct({
        minimumMeters: Schema.Finite,
        maximumMeters: Schema.Finite,
        annualMeanTemperatureC: Schema.Finite,
        annualPrecipitationMm: Schema.Finite,
        rainfallPattern: Schema.NonEmptyString,
      }),
    ),
  }),
)

Schema.Record(
  ProfileContextId,
  Schema.Array(
    Schema.Union([
      Schema.TaggedStruct("LOCATION", {
        placeArticleId: PlaceArticleId,
        ancestorPlaceArticleIds: Schema.Array(PlaceArticleId),
      }),
      Schema.TaggedStruct("ELEVATION", {
        value: Schema.Union([
          Schema.TaggedStruct("MEASURED", {
            source: Schema.NonEmptyString,
            meters: Schema.Finite,
            band: Schema.optionalKey(
              Schema.Struct({
                minimumMeters: Schema.Finite,
                maximumMeters: Schema.Finite,
              }),
            ),
          }),
          Schema.TaggedStruct("DECLARED", {
            meters: Schema.Finite,
            band: Schema.optionalKey(
              Schema.Struct({
                minimumMeters: Schema.Finite,
                maximumMeters: Schema.Finite,
              }),
            ),
          }),
        ]),
      }),
      Schema.TaggedStruct("CLIMATE", {
        value: Schema.TaggedStruct("MEASURED", {
          source: Schema.NonEmptyString,
          annualMeanTemperatureC: Schema.Finite,
          annualPrecipitationMm: Schema.Finite,
          rainfallPattern: Schema.NonEmptyString,
        }),
      }),
      Schema.TaggedStruct("PRODUCTION", {
        value: Schema.TaggedStruct("DECLARED", {
          kind: Schema.NonEmptyString,
        }),
      }),
    ]),
  ),
)

Schema.Struct({
  target: Schema.Union([
    Schema.Struct({
      kind: Schema.Literal("WIKIDATA"),
      wikidataId: WikidataId,
    }),
    Schema.Struct({
      kind: Schema.Literal("GBIF"),
      taxonId: GbifTaxonId,
      checklistKey: GbifChecklistKey,
    }),
  ]),
  selection: Schema.Union([
    Schema.Struct({
      wikidataId: WikidataId,
      articleId: ArticleId,
      provenance: WikidataSelectionProvenance,
    }),
    Schema.Struct({
      taxonId: GbifTaxonId,
      articleId: ArticleId,
      provenance: GbifSelectionProvenance,
      checklistKey: GbifChecklistKey,
    }),
  ]),
  failedAt: Schema.DateTimeUtcFromString,
  error: Schema.Union([
    Schema.Struct({
      kind: Schema.Literal("NOT_FOUND"),
    }),
    Schema.Struct({
      kind: Schema.Literal("REDIRECTED"),
      redirectedToWikidataId: WikidataId,
    }),
  ]),
})

Schema.Struct({
  reportIds: Schema.NonEmptyArray(ReportId),
  target: Schema.Union([
    Schema.Struct({
      kind: Schema.Literal("CLAIM"),
      claimId: ClaimId,
    }),
    Schema.Struct({
      kind: Schema.Literal("OBSERVATION_VALUE"),
      observationId: ObservationId,
      property: Schema.NonEmptyString,
      valueKey: ObservationValueKey,
    }),
  ]),
  verdict: Schema.Literals(["CENSOR", "KEEP", "KEEP_WITH_WARNING"]),
  note: Schema.optionalKey(Schema.NonEmptyString),
  authorIds: Schema.Array(PersonId),
  settledByPersonId: PersonId,
  settledAt: Schema.DateTimeUtcFromString,
})

Schema.Record(
  Schema.Union([ClaimId, ObservationValueKey]),
  Schema.Union([
    Schema.Struct({
      visibility: Schema.Literal("HIDDEN"),
      hiddenBy: Schema.Literals(["OPEN_REPORT", "VERDICT"]),
      reasons: Schema.NonEmptyArray(
        Schema.Literals([
          "ABUSIVE",
          "SPAM",
          "FALSE",
          "DANGEROUS",
          "MISTAKEN",
          "OFF_TOPIC",
          "WRONG_ENTITY",
        ]),
      ),
      openReports: Schema.Array(
        Schema.Struct({
          reportId: ReportId,
          reason: Schema.Literals([
            "ABUSIVE",
            "SPAM",
            "FALSE",
            "DANGEROUS",
            "MISTAKEN",
            "OFF_TOPIC",
            "WRONG_ENTITY",
          ]),
          reportedAt: Schema.DateTimeUtcFromString,
        }),
      ),
    }),
    Schema.Struct({
      visibility: Schema.Literal("WARNED"),
      note: Schema.NonEmptyString,
      settledByReportIds: Schema.NonEmptyArray(ReportId),
      openReports: Schema.Array(
        Schema.Struct({
          reportId: ReportId,
          reason: Schema.Literals([
            "ABUSIVE",
            "SPAM",
            "FALSE",
            "DANGEROUS",
            "MISTAKEN",
            "OFF_TOPIC",
            "WRONG_ENTITY",
          ]),
          reportedAt: Schema.DateTimeUtcFromString,
        }),
      ),
    }),
    Schema.Struct({
      visibility: Schema.Literal("UNDER_REVIEW"),
      openReports: Schema.NonEmptyArray(
        Schema.Struct({
          reportId: ReportId,
          reason: Schema.Literals([
            "ABUSIVE",
            "SPAM",
            "FALSE",
            "DANGEROUS",
            "MISTAKEN",
            "OFF_TOPIC",
            "WRONG_ENTITY",
          ]),
          reportedAt: Schema.DateTimeUtcFromString,
        }),
      ),
    }),
  ]),
)

Schema.Record(
  PersonId,
  Schema.Struct({
    upheldConductVerdicts: Schema.Array(
      Schema.Struct({
        claimId: ClaimId,
        reportIds: Schema.NonEmptyArray(ReportId),
        reasons: Schema.NonEmptyArray(Schema.Literals(["ABUSIVE", "SPAM", "FALSE", "DANGEROUS"])),
        settledAt: Schema.DateTimeUtcFromString,
      }),
    ),
    reports: Schema.Struct({
      upheld: Schema.Int,
      kept: Schema.Int,
      open: Schema.Int,
    }),
  }),
)
